import{_ as t,o as a,c as o,al as r}from"./chunks/framework.BawR2jEz.js";const u=JSON.parse('{"title":"Рубрика «Коллекция exDoc»","description":"Настройка рубрики коллекции — структура полей для типовых элементов контента (слайды, отзывы, FAQ).","frontmatter":{"title":"Рубрика «Коллекция exDoc»","description":"Настройка рубрики коллекции — структура полей для типовых элементов контента (слайды, отзывы, FAQ)."},"headers":[],"relativePath":"rubrics/exdoc-collection/index.md","filePath":"rubrics/exdoc-collection/index.md"}'),d={name:"rubrics/exdoc-collection/index.md"};function c(i,e,l,n,s,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="рубрика-«коллекция-exdoc»" tabindex="-1">Рубрика «Коллекция exDoc» <a class="header-anchor" href="#рубрика-«коллекция-exdoc»" aria-label="Permalink to &quot;Рубрика «Коллекция exDoc»&quot;">​</a></h1><p>Тип: <code>rub_exdoc_collection</code></p><p>Рубрика коллекции определяет структуру полей для типовых элементов контента: слайды, карточки отзывов, элементы FAQ, преимущества и т.д. В отличие от других типов рубрик, коллекция <strong>не имеет собственной страницы</strong> — её элементы выводятся внутри шаблонов других сущностей через поле <code>exdoc_collection_list</code>.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Название</strong></td><td>Имя рубрики (например, «Слайды», «Отзывы», «FAQ»)</td></tr><tr><td><strong>Хэштег</strong></td><td>Уникальный идентификатор</td></tr><tr><td><strong>Статус</strong></td><td>Включена/выключена</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Обратите внимание</p><p>У коллекций <strong>нет шаблона-обёртки</strong> и <strong>нет шаблона страницы</strong>, т.к. коллекция не является самостоятельной страницей.</p></div><h2 id="разделы-формы" tabindex="-1">Разделы формы <a class="header-anchor" href="#разделы-формы" aria-label="Permalink to &quot;Разделы формы&quot;">​</a></h2><h3 id="поля-рубрики" tabindex="-1">Поля рубрики <a class="header-anchor" href="#поля-рубрики" aria-label="Permalink to &quot;Поля рубрики&quot;">​</a></h3><p>Определение полей элемента коллекции. Подробнее см. <a href="/exdoc-docs/fields/">Поля</a>.</p><h3 id="макеты-полеи" tabindex="-1">Макеты полей <a class="header-anchor" href="#макеты-полеи" aria-label="Permalink to &quot;Макеты полей&quot;">​</a></h3><p>Twig-шаблоны для каждого поля рубрики. Определяют, как отдельное поле рендерится на фронте.</p><h3 id="макеты-превью" tabindex="-1">Макеты превью <a class="header-anchor" href="#макеты-превью" aria-label="Permalink to &quot;Макеты превью&quot;">​</a></h3><p>Шаблоны миниатюр для отображения элементов коллекции в списках. Каждый thumb — со своим шаблоном, стилями и скриптами. Вызываются через <code>ex.rubric_thumb()</code>.</p><h3 id="компоненты" tabindex="-1">Компоненты <a class="header-anchor" href="#компоненты" aria-label="Permalink to &quot;Компоненты&quot;">​</a></h3><p>Переиспользуемые Twig-фрагменты, доступные через <code>{{ component(&#39;hashtag&#39;) }}</code>.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./context.html">Объект контекста коллекции</a> — свойства и методы в шаблоне</li><li><a href="/exdoc-docs/fields/exdoc-collection-list/">Поле «Коллекции exDoc»</a> — вывод коллекций в шаблонах</li><li><a href="/exdoc-docs/fields/">Поля</a> — типы полей</li></ul></div>',1)])])}const b=t(d,[["render",c]]);export{u as __pageData,b as default};
